<?php $editing=isset($invoice['id']);$rows=$lines?:[['description'=>'','cost_code_id'=>'','amount'=>'','sort_order'=>1]];?>
<div class="page-header mb-4"><h2 class="page-title"><?=$editing?'تعديل مسودة فاتورة المورد':'إنشاء فاتورة مورد'?></h2></div>
<form id="supplier-invoice-form" method="post" action="<?=$editing?'/supplier-invoices/'.(int)$invoice['id'].'/edit':'/supplier-invoices'?>"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><div class="card mb-4"><div class="card-body"><div class="row g-3">
<div class="col-md-4"><label class="form-label required">المورد</label><select id="supplier-invoice-vendor" class="form-select" name="vendor_id" required><option value="">اختر</option><?php foreach($references['vendors'] as $item):?><option value="<?=(int)$item['id']?>" <?=($invoice['vendor_id']??'')==$item['id']?'selected':''?>><?=e($item['vendor_code'].' - '.$item['name'])?></option><?php endforeach;?></select></div>
<div class="col-md-4"><label class="form-label required">المشروع</label><select id="supplier-invoice-project" class="form-select" name="project_id" required><option value="">اختر</option><?php foreach($references['projects'] as $item):?><option value="<?=(int)$item['id']?>" <?=($invoice['project_id']??'')==$item['id']?'selected':''?>><?=e($item['project_code'].' - '.$item['name'])?></option><?php endforeach;?></select></div>
<div class="col-md-4"><label class="form-label">أمر الشراء المعتمد</label><select id="supplier-invoice-po" class="form-select" name="purchase_order_id"><option value="">بدون أمر شراء</option><?php foreach($references['purchase_orders'] as $item):?><option value="<?=(int)$item['id']?>" data-vendor-id="<?=(int)$item['vendor_id']?>" data-project-id="<?=(int)$item['project_id']?>" <?=($invoice['purchase_order_id']??'')==$item['id']?'selected':''?>><?=e($item['po_code'].' — '.decimal_format($item['total_amount']))?></option><?php endforeach;?></select><small class="form-hint">تظهر فقط أوامر الشراء المعتمدة المطابقة للمورد والمشروع.</small></div>
<div class="col-md-4"><label class="form-label required">رقم فاتورة المورد</label><input class="form-control" name="invoice_number" maxlength="100" required value="<?=e((string)($invoice['invoice_number']??''))?>"></div><div class="col-md-3"><label class="form-label required">تاريخ الفاتورة</label><input class="form-control" type="date" name="invoice_date" required value="<?=e((string)($invoice['invoice_date']??date('Y-m-d')))?>"></div><div class="col-md-3"><label class="form-label">تاريخ الاستحقاق</label><input class="form-control" type="date" name="due_date" value="<?=e((string)($invoice['due_date']??''))?>"></div><div class="col-md-3"><label class="form-label">المرجع</label><input class="form-control" name="reference" maxlength="190" value="<?=e((string)($invoice['reference']??''))?>"></div><div class="col-12"><label class="form-label">ملاحظات</label><textarea class="form-control" name="notes"><?=e((string)($invoice['notes']??''))?></textarea></div></div></div></div>
<div class="card mb-4"><div class="card-header d-flex"><h3 class="card-title">بنود الفاتورة</h3><button class="btn btn-sm me-auto" type="button" id="add-invoice-line">إضافة بند</button></div><div class="table-responsive"><table class="table" id="invoice-lines"><thead><tr><th>الوصف</th><th>كود التكلفة</th><th>المبلغ</th><th></th></tr></thead><tbody><?php foreach($rows as $offset=>$line):?><tr><td><input class="form-control" name="lines[<?=$offset?>][description]" required maxlength="500" value="<?=e((string)$line['description'])?>"></td><td><select class="form-select" name="lines[<?=$offset?>][cost_code_id]" required><option value="">اختر</option><?php foreach($references['codes'] as $code):?><option value="<?=(int)$code['id']?>" <?=$line['cost_code_id']==$code['id']?'selected':''?>><?=e($code['section_code'].' / '.$code['cost_code'].' - '.$code['name'])?></option><?php endforeach;?></select></td><td><input class="form-control invoice-line-amount" name="lines[<?=$offset?>][amount]" required inputmode="decimal" value="<?=e((string)$line['amount'])?>"></td><td><button class="btn btn-danger btn-sm remove-invoice-line" type="button">حذف</button></td></tr><?php endforeach;?></tbody></table></div><div class="card-footer text-start">الإجمالي التقديري: <strong id="invoice-total">0.00</strong></div></div><button class="btn btn-primary">حفظ المسودة</button> <a class="btn" href="/supplier-invoices">رجوع</a></form>
<template id="invoice-line-template"><tr><td><input class="form-control" data-name="description" required maxlength="500"></td><td><select class="form-select" data-name="cost_code_id" required><option value="">اختر</option><?php foreach($references['codes'] as $code):?><option value="<?=(int)$code['id']?>"><?=e($code['section_code'].' / '.$code['cost_code'].' - '.$code['name'])?></option><?php endforeach;?></select></td><td><input class="form-control invoice-line-amount" data-name="amount" required inputmode="decimal"></td><td><button class="btn btn-danger btn-sm remove-invoice-line" type="button">حذف</button></td></tr></template><script src="/assets/js/modules/supplier-invoice-form.js" defer></script>
